import { useEffect, useMemo, useState } from 'react';
import {
  Activity, BarChart3, BellRing, Bot, Building2, CalendarClock, Check, ChevronDown, CircleDot,
  Copy, Download, FileClock, GitBranch, Headphones, KeyRound, ListFilter, LockKeyhole, Network, PhoneCall,
  PhoneForwarded, PhoneIncoming, Plus, QrCode as QrCodeIcon, RefreshCw, Route, Save, Search,
  Server, Settings2, ShieldCheck, Smartphone, Trash2, Upload, UserRoundPlus, Users, Voicemail, X
} from 'lucide-react';
import QRCode from 'qrcode';
import { api } from '../lib/api';
import { buildDialingDirectory } from '../lib/countries';
import './admin.css';

const emptyUser = { extension: '', name: '', email: '', mobile: '', department: 'General', role: 'user' };
const defaultProfile = { outboundCallerId: '', did: '', twoFactorEnabled: false, noAnswerSeconds: 25, forwardBusy: '', forwardNoAnswer: '', forwardUnavailable: '', simultaneousRing: '', voicemailEnabled: true, voicemailEmail: true, voicemailTranscription: false, schedule: 'Use office hours', permissions: { international: true, transfer: true, video: true, recording: false, reports: false } };
const emptyTrunk = { name: '', proxy: '', username: '', password: '', transport: 'TLS', destinationUri: '', active: true, policy: { inboundEnabled: true, outboundEnabled: true, inboundDids: [], defaultDestination: '', outboundPrefix: '', priority: 1, failoverTrunkId: '', channelLimit: 10, codecs: ['PCMU', 'PCMA'], mediaEncryption: true, notes: '' } };
const countryOptions = buildDialingDirectory();
const nav = [
  { group: 'OPERATIONS', items: [['dashboard', Activity, 'Dashboard'], ['users', Users, 'Users'], ['numbers', PhoneIncoming, 'Phone numbers'], ['voice', Bot, 'Voice & AI']] },
  { group: 'ROUTING', items: [['outbound', Route, 'Outbound rules'], ['hours', CalendarClock, 'Office hours'], ['handling', GitBranch, 'Call handling']] },
  { group: 'INSIGHTS', items: [['reports', BarChart3, 'Reports'], ['events', FileClock, 'Event log']] },
  { group: 'SYSTEM', items: [['trunks', Network, 'SIP trunks'], ['developer', KeyRound, 'Developer API'], ['system', Settings2, 'System']] },
];
const uid = (prefix) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;

function Status({ good = false, warn = false, children }) { return <span className={`status-pill ${good ? 'good' : warn ? 'warn' : ''}`}><i />{children}</span>; }
function Toggle({ value, onChange, label }) { return <button type="button" role="switch" aria-checked={value} className={`toggle ${value ? 'on' : ''}`} onClick={() => onChange(!value)}><i />{label && <span>{label}</span>}</button>; }
function PageHeader({ eyebrow, title, subtitle, children }) { return <header className="page-header"><div><p>{eyebrow}</p><h1>{title}</h1><span>{subtitle}</span></div><div className="page-actions">{children}</div></header>; }
function Field({ label, children, wide = false, help }) { return <label className={`field ${wide ? 'wide' : ''}`}><span>{label}</span>{children}{help && <small>{help}</small>}</label>; }
function Modal({ title, subtitle, onClose, wide = false, children }) { return <div className="modal-layer"><section className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true"><header><div><h2>{title}</h2><p>{subtitle}</p></div><button className="icon-button" onClick={onClose} title="Close"><X /></button></header>{children}</section></div>; }
function Empty({ icon: Icon, title, copy }) { return <div className="empty"><Icon /><strong>{title}</strong><span>{copy}</span></div>; }

function Dashboard({ overview, extensions, config, events, setSection }) {
  const metrics = overview?.metrics || {};
  const organization = config.organizations.find((item) => item.id === config.activeOrganizationId) || config.organizations[0];
  const readiness = [
    ['Credential connection', overview?.connection?.active, overview?.connection?.name || 'Vocivo Mobile'],
    ['Mobile incoming push', overview?.connection?.pushConfigured, overview?.connection?.pushConfigured ? 'Configured' : 'Apple VoIP certificate required'],
    ['AI receptionist', config.ai.enabled && config.ai.assistantId, config.ai.enabled ? (config.ai.assistantId ? 'Active' : 'Needs synchronization') : 'Disabled'],
    [`Extension range ${organization?.extensionStart || ''}-${organization?.extensionEnd || ''}`, organization?.internalCallingEnabled, `${extensions.length} of ${organization ? organization.extensionEnd - organization.extensionStart + 1 : 0} slots assigned`],
  ];
  return <div className="page"><PageHeader eyebrow="SYSTEM OVERVIEW" title="Dashboard" subtitle="Live voice infrastructure, users and routing at a glance."><button className="secondary" onClick={() => setSection('events')}><FileClock /> Event log</button></PageHeader>
    <div className="metrics"><div><Users /><span>Active users</span><strong>{metrics.activeExtensions ?? extensions.length}</strong><small>{extensions.length} extensions</small></div><div><PhoneIncoming /><span>Company numbers</span><strong>{metrics.phoneNumbers ?? 0}</strong><small>Inbound lines</small></div><div><Network /><span>SIP trunks</span><strong>1</strong><small>Managed connection</small></div><div><Activity /><span>Balance</span><strong>{metrics.currency || 'USD'} {Number(metrics.balance || 0).toFixed(2)}</strong><small>Live Telnyx account</small></div></div>
    <section className="band"><div className="section-title"><div><h2>System readiness</h2><p>Items that directly affect inbound and internal calls.</p></div></div><div className="readiness">{readiness.map(([label, good, detail]) => <div key={label}><span>{label}</span><strong>{detail}</strong><Status good={good} warn={!good}>{good ? 'Ready' : 'Attention'}</Status></div>)}</div></section>
    <section className="band"><div className="section-title"><div><h2>Recent activity</h2><p>Latest Telnyx call events from the last 24 hours.</p></div><button className="text-button" onClick={() => setSection('events')}>View all</button></div>{events.length ? <div className="event-list">{events.slice(0, 8).map((e, i) => <div key={e.call_leg_id || i}><CircleDot /><strong>{e.name || 'Call event'}</strong><span>{e.call_session_id || 'Voice platform'}</span><time>{e.event_timestamp ? new Date(e.event_timestamp).toLocaleString() : ''}</time></div>)}</div> : <Empty icon={FileClock} title="No recent call events" copy="New call activity will appear here." />}</section>
  </div>;
}

const userTabs = [['general', Users, 'General'], ['provision', QrCodeIcon, 'Provisioning'], ['forward', PhoneForwarded, 'Call forwarding'], ['schedule', CalendarClock, 'Schedule'], ['devices', Smartphone, 'Devices'], ['presence', CircleDot, 'Presence'], ['voicemail', Voicemail, 'Voicemail'], ['permissions', LockKeyhole, 'Permissions']];
function UserEditor({ draft, profile, organization, onDraft, onProfile, onClose, onSave, onProvision, busy }) {
  const [tab, setTab] = useState('general');
  const permissions = { international: 'International outbound calling', transfer: 'Transfer and attended transfer', video: 'Video calling', recording: 'Call recording', reports: 'View call reports' };
  return <Modal wide title={draft.id ? `Edit ${draft.name}` : 'Add user'} subtitle={draft.id ? `Extension ${draft.extension}` : 'Create identity, extension and app access'} onClose={onClose}>
    <form className="user-editor" onSubmit={onSave}><nav className="editor-tabs">{userTabs.map(([id, Icon, label]) => <button type="button" key={id} className={tab === id ? 'active' : ''} onClick={() => setTab(id)}><Icon />{label}</button>)}</nav><div className="editor-body">
      {tab === 'general' && <><div className="form-grid"><Field label="Extension" help={draft.id ? 'Changing an existing extension can affect saved contacts.' : `Leave blank to assign the next free slot in ${organization?.extensionStart || 2000}-${organization?.extensionEnd || 2019}.`}><input autoFocus value={draft.extension} onChange={(e) => onDraft({ ...draft, extension: e.target.value.replace(/\D/g, '').slice(0, 5) })} placeholder="Auto assign" /></Field><Field label="Role"><select value={draft.role} onChange={(e) => onDraft({ ...draft, role: e.target.value })}><option value="user">User</option><option value="manager">Manager</option><option value="admin">System administrator</option></select></Field><Field label="Display name"><input value={draft.name} onChange={(e) => onDraft({ ...draft, name: e.target.value })} required /></Field><Field label="Email"><input type="email" value={draft.email} onChange={(e) => onDraft({ ...draft, email: e.target.value })} /></Field><Field label="Mobile"><input value={draft.mobile} onChange={(e) => onDraft({ ...draft, mobile: e.target.value })} placeholder="+966..." /></Field><Field label="Department"><input value={draft.department} onChange={(e) => onDraft({ ...draft, department: e.target.value })} /></Field><Field label="Outbound caller ID"><input value={profile.outboundCallerId} onChange={(e) => onProfile({ ...profile, outboundCallerId: e.target.value })} placeholder="Use company default" /></Field><Field label="Assigned DID"><input value={profile.did} onChange={(e) => onProfile({ ...profile, did: e.target.value })} placeholder="Optional direct number" /></Field></div><div className="setting-line"><div><strong>Two-factor authentication</strong><span>Require additional verification for admin access.</span></div><Toggle value={profile.twoFactorEnabled} onChange={(twoFactorEnabled) => onProfile({ ...profile, twoFactorEnabled })} /></div></>}
      {tab === 'provision' && <div className="provision-panel"><QrCodeIcon /><h3>Mobile app provisioning</h3><p>Generate a ten-minute QR code that securely enrolls this user without displaying the SIP password.</p>{draft.id ? <button type="button" className="primary" onClick={() => onProvision(draft)}><QrCodeIcon /> Generate setup QR</button> : <Status warn>Save the user first</Status>}</div>}
      {tab === 'forward' && <div className="form-grid"><Field label="No-answer timeout"><div className="suffix-input"><input type="number" min="10" max="120" value={profile.noAnswerSeconds} onChange={(e) => onProfile({ ...profile, noAnswerSeconds: Number(e.target.value) })} /><span>seconds</span></div></Field><Field label="Simultaneous ring"><input value={profile.simultaneousRing} onChange={(e) => onProfile({ ...profile, simultaneousRing: e.target.value })} placeholder="Extension or E.164 number" /></Field><Field label="When busy"><input value={profile.forwardBusy} onChange={(e) => onProfile({ ...profile, forwardBusy: e.target.value })} placeholder="Voicemail, extension or number" /></Field><Field label="When unanswered"><input value={profile.forwardNoAnswer} onChange={(e) => onProfile({ ...profile, forwardNoAnswer: e.target.value })} /></Field><Field label="When unavailable" wide><input value={profile.forwardUnavailable} onChange={(e) => onProfile({ ...profile, forwardUnavailable: e.target.value })} /></Field></div>}
      {tab === 'schedule' && <div className="form-grid"><Field label="Routing schedule" wide><select value={profile.schedule} onChange={(e) => onProfile({ ...profile, schedule: e.target.value })}><option>Use office hours</option><option>Always available</option><option>Custom schedule</option></select></Field><div className="info-strip wide"><CalendarClock /><span>Office hours and holidays are managed centrally.</span></div></div>}
      {tab === 'devices' && <div className="device-list"><div><Smartphone /><div><strong>Vocivo iOS app</strong><span>{draft.id ? 'Ready for QR enrollment or reset' : 'Available after creation'}</span></div><Status good={Boolean(draft.id)}>{draft.id ? 'Provisionable' : 'Pending'}</Status></div><div><Headphones /><div><strong>SIP desk phone or softphone</strong><span>TLS registration through sip.telnyx.com</span></div><Status good={Boolean(draft.sipUsername)}>{draft.sipUsername ? 'Credential issued' : 'Pending'}</Status></div></div>}
      {tab === 'presence' && <div className="form-grid"><Field label="Presence status"><select><option>Available</option><option>Do not disturb</option><option>Away</option></select></Field><Field label="BLF visibility"><select><option>Organization</option><option>Department only</option><option>Private</option></select></Field><div className="info-strip wide"><CircleDot /><span>Live presence is published after this extension registers.</span></div></div>}
      {tab === 'voicemail' && <>{[['voicemailEnabled', 'Enable voicemail', 'Answer calls when the user cannot.'], ['voicemailEmail', 'Email notification', 'Send a notice for each new voicemail.'], ['voicemailTranscription', 'AI transcription', 'Create searchable text from voicemail audio.']].map(([key, title, copy]) => <div className="setting-line" key={key}><div><strong>{title}</strong><span>{copy}</span></div><Toggle value={profile[key]} onChange={(value) => onProfile({ ...profile, [key]: value })} /></div>)}</>}
      {tab === 'permissions' && <div className="permission-list">{Object.entries(permissions).map(([key, label]) => <div className="setting-line" key={key}><div><strong>{label}</strong><span>Applied to extension {draft.extension || 'after creation'}.</span></div><Toggle value={profile.permissions[key]} onChange={(value) => onProfile({ ...profile, permissions: { ...profile.permissions, [key]: value } })} /></div>)}</div>}
    </div><footer><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}><Save /> Save user</button></footer></form>
  </Modal>;
}

function UsersPage({ items, onAdd, onEdit, onDelete, onProvision, onExport }) {
  const [query, setQuery] = useState(''); const [selected, setSelected] = useState([]);
  const filtered = useMemo(() => items.filter((x) => `${x.extension} ${x.name} ${x.department} ${x.email}`.toLowerCase().includes(query.toLowerCase())), [items, query]);
  return <div className="page"><PageHeader eyebrow="PEOPLE" title="Users" subtitle="Identity, extension, routing, devices, voicemail and permissions."><button className="secondary" onClick={onExport}><Download /> Export</button><button className="primary" onClick={onAdd}><UserRoundPlus /> Add user</button></PageHeader><div className="toolbar"><label><Search /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search name, extension, department or email" /></label><span>{selected.length ? `${selected.length} selected` : `${filtered.length} users`}</span></div><div className="table-shell"><table><thead><tr><th><input type="checkbox" checked={filtered.length > 0 && selected.length === filtered.length} onChange={(e) => setSelected(e.target.checked ? filtered.map((x) => x.id) : [])} /></th><th>User</th><th>Extension</th><th>Department</th><th>Role</th><th>App setup</th><th>Status</th><th /></tr></thead><tbody>{filtered.map((item) => <tr key={item.id}><td><input type="checkbox" checked={selected.includes(item.id)} onChange={(e) => setSelected(e.target.checked ? [...selected, item.id] : selected.filter((id) => id !== item.id))} /></td><td><strong>{item.name}</strong><small>{item.email || item.mobile || 'No contact detail'}</small></td><td><button className="extension" onClick={() => onEdit(item)}>{item.extension}</button></td><td>{item.department}</td><td><span className="role">{item.role}</span></td><td><button className="qr-action" onClick={() => onProvision(item)}><QrCodeIcon /> Setup QR</button></td><td><Status good={item.status === 'active'}>{item.status}</Status></td><td><div className="row-actions"><button onClick={() => onEdit(item)}>Edit</button><button className="danger" onClick={() => onDelete(item)}><Trash2 /></button></div></td></tr>)}</tbody></table>{!filtered.length && <Empty icon={Users} title="No users found" copy="Create a user or change the current search." />}</div><div className="info-strip"><PhoneCall /><span>Calls between registered Vocivo extensions use internal SIP routing and do not consume public PSTN minutes.</span></div></div>;
}

function VoicePage({ business, setBusiness, config, setConfig, voices, onSaveBusiness, onSaveAI, onUpload, busy }) {
  const ai = config.ai;
  const voiceOptions = <><optgroup label="Vocivo in-house voices">{(voices?.voices || []).map((voice) => <option key={voice.id} value={voice.id}>{voice.name} · {voice.gender} · {voice.accent}</option>)}</optgroup><optgroup label="Carrier fallback voices">{(voices?.carrierFallbacks || []).map((voice) => <option key={voice.id} value={voice.id}>{voice.name} · {voice.gender}</option>)}</optgroup></>;
  return <div className="page"><PageHeader eyebrow="VOICE AUTOMATION" title="Voice & AI" subtitle="Direct ringing, IVR menus, an interactive receptionist and company audio."><button className="primary" onClick={onSaveBusiness} disabled={busy}><Save /> Apply routing</button></PageHeader>
    <section className="band"><div className="section-title"><div><h2>Inbound mode</h2><p>Choose exactly how the company number answers.</p></div></div><div className="mode-selector"><button className={!business.enabled && !ai.enabled ? 'active' : ''} onClick={() => { setBusiness({ ...business, enabled: false }); setConfig({ ...config, ai: { ...ai, enabled: false } }); }}><PhoneIncoming /><strong>Direct</strong><span>Ring staff immediately</span></button><button className={business.enabled && !ai.enabled ? 'active' : ''} onClick={() => { setBusiness({ ...business, enabled: true }); setConfig({ ...config, ai: { ...ai, enabled: false } }); }}><ListFilter /><strong>Voice menu</strong><span>Divisions and extensions</span></button><button className={ai.enabled ? 'active' : ''} onClick={() => setConfig({ ...config, ai: { ...ai, enabled: true } })}><Bot /><strong>AI receptionist</strong><span>Natural conversation</span></button></div></section>
    <section className="band"><div className="section-title"><div><h2>Interactive AI receptionist</h2><p>Telnyx listens, answers approved questions and can guide callers to a human.</p></div><Toggle value={ai.enabled} label={ai.enabled ? 'Enabled' : 'Disabled'} onChange={(enabled) => setConfig({ ...config, ai: { ...ai, enabled } })} /></div><div className="form-grid"><Field label="Assistant name"><input value={ai.name} onChange={(e) => setConfig({ ...config, ai: { ...ai, name: e.target.value } })} /></Field><Field label="Fallback extension"><input value={ai.fallbackExtension} onChange={(e) => setConfig({ ...config, ai: { ...ai, fallbackExtension: e.target.value.replace(/\D/g, '') } })} /></Field><Field label="Voice" help="Vocivo voices are used for generated prompts; interactive conversation uses the matching carrier fallback until the in-house dialog media service is enabled."><select value={ai.voice} onChange={(e) => setConfig({ ...config, ai: { ...ai, voice: e.target.value } })}>{voiceOptions}</select></Field><Field label="Language"><select value={ai.language} onChange={(e) => setConfig({ ...config, ai: { ...ai, language: e.target.value } })}><option value="en">English</option><option value="ar">Arabic</option><option value="fr">French</option><option value="es">Spanish</option></select></Field><Field label="Opening greeting" wide><textarea rows="3" value={ai.greeting} onChange={(e) => setConfig({ ...config, ai: { ...ai, greeting: e.target.value } })} /></Field><Field label="Assistant behavior" wide><textarea rows="5" value={ai.instructions} onChange={(e) => setConfig({ ...config, ai: { ...ai, instructions: e.target.value } })} /></Field><Field label="Approved company knowledge" wide help="Services, office information and FAQs. The assistant is instructed to stay within this source."><textarea rows="7" value={ai.knowledge} onChange={(e) => setConfig({ ...config, ai: { ...ai, knowledge: e.target.value } })} /></Field></div>{[['transferEnabled', 'Human escalation', 'Offer to connect the caller when AI cannot answer.'], ['summariesEnabled', 'Conversation summaries', 'Request post-call insights from Telnyx.']].map(([key, title, copy]) => <div className="setting-line" key={key}><div><strong>{title}</strong><span>{copy}</span></div><Toggle value={ai[key]} onChange={(value) => setConfig({ ...config, ai: { ...ai, [key]: value } })} /></div>)}<div className="section-footer"><Status good={Boolean(ai.assistantId)} warn={!ai.assistantId}>{ai.assistantId ? 'Synchronized with Telnyx' : 'Not synchronized'}</Status><button className="primary" onClick={onSaveAI} disabled={busy}><Bot /> Save and synchronize AI</button></div></section>
    <section className="band"><div className="section-title"><div><h2>Classic IVR and company sound</h2><p>Used when Voice menu is selected.</p></div><Status good={voices?.provider?.healthy} warn={!voices?.provider?.healthy}>{voices?.provider?.healthy ? 'Vocivo voice online' : voices?.provider?.configured ? 'Voice service unavailable' : 'Carrier fallback active'}</Status></div><div className="form-grid"><Field label="Company name"><input value={business.companyName || ''} onChange={(e) => setBusiness({ ...business, companyName: e.target.value })} /></Field><Field label="Voice" help="Kokoro-82M is self-hosted under Apache-2.0."><select value={business.voice || ''} onChange={(e) => setBusiness({ ...business, voice: e.target.value })}>{voiceOptions}</select></Field><Field label="Welcome message" wide><textarea rows="3" value={business.greeting || ''} onChange={(e) => setBusiness({ ...business, greeting: e.target.value })} /></Field><Field label="Message while waiting" wide><textarea rows="3" value={business.waitingMessage || ''} onChange={(e) => setBusiness({ ...business, waitingMessage: e.target.value })} /></Field></div><div className="department-grid">{(business.departments || []).map((name, index) => <div key={index}><span>{index + 1}</span><input value={name} onChange={(e) => setBusiness({ ...business, departments: business.departments.map((x, i) => i === index ? e.target.value : x) })} />{business.departments.length > 2 && <button onClick={() => setBusiness({ ...business, departments: business.departments.filter((_, i) => i !== index) })}><Trash2 /></button>}</div>)}{business.departments?.length < 5 && <button className="add-tile" onClick={() => setBusiness({ ...business, departments: [...business.departments, ''] })}><Plus /> Add division</button>}</div><div className="branding-row"><div className="brand-preview" style={business.backgroundImageUrl ? { backgroundImage: `linear-gradient(rgba(5,29,55,.42),rgba(5,29,55,.72)),url(${business.backgroundImageUrl})` } : undefined}><strong>Ready for incoming calls</strong><span>{business.companyName}</span></div><label className="upload-control"><Upload /> Upload home background<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(e) => onUpload(e.target.files?.[0])} /></label></div></section>
  </div>;
}

function OutboundPage({ config, setConfig, onSave }) {
  const add = () => setConfig({ ...config, outboundRules: [...config.outboundRules, { id: uid('rule'), name: 'New outbound rule', prefix: '', extensionRange: '', numberLength: '', department: 'All', routes: ['Vocivo Telnyx'], enabled: true }] });
  const update = (id, patch) => setConfig({ ...config, outboundRules: config.outboundRules.map((x) => x.id === id ? { ...x, ...patch } : x) });
  return <div className="page"><PageHeader eyebrow="CALL ROUTING" title="Outbound rules" subtitle="Prioritized patterns determine how users reach public destinations."><button className="secondary" onClick={add}><Plus /> Add rule</button><button className="primary" onClick={onSave}><Save /> Save rules</button></PageHeader><div className="table-shell"><table><thead><tr><th>#</th><th>Rule</th><th>Prefix</th><th>Extensions</th><th>Length</th><th>Department</th><th>Route 1</th><th>Enabled</th><th /></tr></thead><tbody>{config.outboundRules.map((rule, index) => <tr key={rule.id}><td><strong>{index + 1}</strong></td><td><input value={rule.name} onChange={(e) => update(rule.id, { name: e.target.value })} /></td><td><input value={rule.prefix} onChange={(e) => update(rule.id, { prefix: e.target.value })} /></td><td><input value={rule.extensionRange} onChange={(e) => update(rule.id, { extensionRange: e.target.value })} placeholder="All" /></td><td><input value={rule.numberLength} onChange={(e) => update(rule.id, { numberLength: e.target.value })} placeholder="Any" /></td><td><input value={rule.department} onChange={(e) => update(rule.id, { department: e.target.value })} /></td><td><input value={rule.routes[0] || ''} onChange={(e) => update(rule.id, { routes: [e.target.value, ...rule.routes.slice(1)] })} /></td><td><Toggle value={rule.enabled} onChange={(enabled) => update(rule.id, { enabled })} /></td><td><button className="danger icon-button" onClick={() => setConfig({ ...config, outboundRules: config.outboundRules.filter((x) => x.id !== rule.id) })}><Trash2 /></button></td></tr>)}</tbody></table></div><div className="info-strip"><Route /><span>Rules are evaluated from top to bottom. Keep emergency calling separate and verify the service address before enabling it.</span></div></div>;
}

function HoursPage({ config, setConfig, onSave }) {
  const hours = config.officeHours; const setHours = (patch) => setConfig({ ...config, officeHours: { ...hours, ...patch } }); const updateDay = (day, patch) => setHours({ weekdays: { ...hours.weekdays, [day]: { ...hours.weekdays[day], ...patch } } });
  return <div className="page"><PageHeader eyebrow="ORGANIZATION SCHEDULE" title="Office hours" subtitle="Control open, closed and holiday routing in one timezone."><button className="primary" onClick={onSave}><Save /> Save schedule</button></PageHeader><section className="band"><div className="section-title"><div><h2>Weekly hours</h2><p>Applied to users and routing objects using company hours.</p></div><select value={hours.timezone} onChange={(e) => setHours({ timezone: e.target.value })}><option>Asia/Riyadh</option><option>Europe/London</option><option>Africa/Lagos</option><option>America/New_York</option></select></div><div className="hours-list">{Object.entries(hours.weekdays).map(([day, value]) => <div key={day}><Toggle value={value.enabled} onChange={(enabled) => updateDay(day, { enabled })} /><strong>{day}</strong>{value.enabled ? <><input type="time" value={value.start} onChange={(e) => updateDay(day, { start: e.target.value })} /><span>to</span><input type="time" value={value.end} onChange={(e) => updateDay(day, { end: e.target.value })} /></> : <span className="closed">Closed</span>}</div>)}</div></section><section className="band"><div className="section-title"><div><h2>Holidays and closures</h2><p>Override normal hours on company dates.</p></div><button className="secondary" onClick={() => setHours({ holidays: [...hours.holidays, { id: uid('holiday'), name: 'Company holiday', date: '', destination: 'Main voicemail' }] })}><Plus /> Add holiday</button></div>{hours.holidays.length ? <div className="compact-table">{hours.holidays.map((h) => <div key={h.id}><input value={h.name} onChange={(e) => setHours({ holidays: hours.holidays.map((x) => x.id === h.id ? { ...x, name: e.target.value } : x) })} /><input type="date" value={h.date} onChange={(e) => setHours({ holidays: hours.holidays.map((x) => x.id === h.id ? { ...x, date: e.target.value } : x) })} /><input value={h.destination} onChange={(e) => setHours({ holidays: hours.holidays.map((x) => x.id === h.id ? { ...x, destination: e.target.value } : x) })} /><button className="danger icon-button" onClick={() => setHours({ holidays: hours.holidays.filter((x) => x.id !== h.id) })}><Trash2 /></button></div>)}</div> : <Empty icon={CalendarClock} title="No holiday overrides" copy="Normal weekly hours are currently used all year." />}</section></div>;
}

function HandlingPage({ config, setConfig, onSave }) {
  const h = config.callHandling; const setHandling = (key, value) => setConfig({ ...config, callHandling: { ...h, [key]: value } });
  const defs = [['ringGroups', BellRing, 'Ring groups', { name: 'New ring group', extension: '', strategy: 'Ring all', members: [], timeout: 25, fallback: 'Main voicemail' }], ['queues', Headphones, 'Queues', { name: 'New call queue', extension: '', strategy: 'Longest idle', members: [], maxWait: 180, fallback: 'Main voicemail' }], ['ivrs', ListFilter, 'Digital receptionists', { name: 'New voice menu', extension: '', greeting: 'Welcome. Please choose an option.', options: {} }]];
  return <div className="page"><PageHeader eyebrow="INBOUND ROUTING" title="Call handling" subtitle="Build ring groups, queues and digital receptionists around extensions."><button className="primary" onClick={onSave}><Save /> Save call handling</button></PageHeader>{defs.map(([key, Icon, label, blank]) => <section className="band" key={key}><div className="section-title"><div><h2>{label}</h2><p>{key === 'ringGroups' ? 'Ring selected colleagues together or in order.' : key === 'queues' ? 'Hold callers and distribute them to available agents.' : 'Route keypad choices to extensions, queues and departments.'}</p></div><button className="secondary" onClick={() => setHandling(key, [...h[key], { ...blank, id: uid(key) }])}><Plus /> Add</button></div>{h[key].length ? <div className="object-list">{h[key].map((item) => <div key={item.id}><span className="object-icon"><Icon /></span><div><input className="object-name" value={item.name} onChange={(e) => setHandling(key, h[key].map((x) => x.id === item.id ? { ...x, name: e.target.value } : x))} /><small>Extension {item.extension || 'not assigned'} · {item.strategy || 'Voice menu'}</small></div><span>{item.members?.length || Object.keys(item.options || {}).length} targets</span><button className="danger icon-button" onClick={() => setHandling(key, h[key].filter((x) => x.id !== item.id))}><Trash2 /></button></div>)}</div> : <Empty icon={Icon} title={`No ${label.toLowerCase()}`} copy="Add one to expand company routing." />}</section>)}</div>;
}

function ReportsPage({ events }) {
  const initiated = events.filter((e) => e.name === 'call.initiated').length, answered = events.filter((e) => e.name === 'call.answered').length, ended = events.filter((e) => e.name === 'call.hangup').length;
  return <div className="page"><PageHeader eyebrow="LIVE TELNYX DATA" title="Reports" subtitle="Operational call activity from the last 24 hours."><button className="secondary" onClick={() => window.print()}><Download /> Export view</button></PageHeader><div className="metrics report-metrics"><div><PhoneIncoming /><span>Calls initiated</span><strong>{initiated}</strong><small>Call events</small></div><div><Check /><span>Answered legs</span><strong>{answered}</strong><small>Connected events</small></div><div><PhoneCall /><span>Ended legs</span><strong>{ended}</strong><small>Hangup events</small></div><div><BarChart3 /><span>Answer ratio</span><strong>{initiated ? `${Math.round(answered / initiated * 100)}%` : '—'}</strong><small>Answered / initiated</small></div></div><section className="band"><div className="section-title"><div><h2>Call event timeline</h2><p>Use Event log for lower-level diagnostics and identifiers.</p></div></div><div className="event-list">{events.slice(0, 30).map((e, i) => <div key={e.call_leg_id || i}><CircleDot /><strong>{e.name}</strong><span>{e.call_session_id || 'No session ID'}</span><time>{e.event_timestamp ? new Date(e.event_timestamp).toLocaleString() : ''}</time></div>)}</div></section></div>;
}
function EventsPage({ events }) { const [q, setQ] = useState(''); const rows = events.filter((e) => JSON.stringify(e).toLowerCase().includes(q.toLowerCase())); return <div className="page"><PageHeader eyebrow="DIAGNOSTICS" title="Event log" subtitle="Telnyx voice events, sessions and call legs from the last 24 hours." /><div className="toolbar"><label><Search /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search event, session or call leg" /></label><span>{rows.length} events</span></div><div className="table-shell"><table><thead><tr><th>Severity</th><th>Date</th><th>Event</th><th>Call session</th><th>Call leg</th><th>Type</th></tr></thead><tbody>{rows.map((e, i) => <tr key={`${e.call_leg_id}-${i}`}><td><Status good={!String(e.name).includes('failed')}>{String(e.name).includes('failed') ? 'Error' : 'Info'}</Status></td><td>{e.event_timestamp ? new Date(e.event_timestamp).toLocaleString() : ''}</td><td><strong>{e.name}</strong></td><td><code>{e.call_session_id || '—'}</code></td><td><code>{e.call_leg_id || '—'}</code></td><td>{e.type || 'webhook'}</td></tr>)}</tbody></table>{!rows.length && <Empty icon={FileClock} title="No matching events" copy="Try a different search." />}</div></div>; }

function DeveloperPage({ data, revealedToken, onCreate, onRevoke, onClearToken }) {
  return <div className="page"><PageHeader eyebrow="PROGRAMMABLE TELECOM" title="Developer API" subtitle="Tenant-scoped APIs for calls, extensions, numbers and events."><button className="primary" onClick={onCreate}><KeyRound /> Create API key</button></PageHeader>
    {revealedToken && <section className="band"><div className="section-title"><div><h2>New API key</h2><p>This secret is shown once. Store it in a password manager or server environment.</p></div><button className="icon-button" title="Dismiss" onClick={onClearToken}><X /></button></div><div className="info-strip"><code>{revealedToken}</code><button className="secondary" onClick={() => navigator.clipboard.writeText(revealedToken)}><Copy /> Copy</button></div></section>}
    <section className="band"><div className="section-title"><div><h2>API keys</h2><p>Keys are isolated to the active organization and can be revoked immediately.</p></div></div>{data?.length ? <div className="object-list">{data.map((item) => <div key={item.id}><span className="object-icon"><KeyRound /></span><div><strong>{item.name}</strong><small>{item.prefix}... · {item.scopes.join(', ')}</small></div><Status good={!item.revokedAt}>{item.revokedAt ? 'Revoked' : 'Active'}</Status>{!item.revokedAt && <button className="danger icon-button" title="Revoke API key" onClick={() => onRevoke(item)}><Trash2 /></button>}</div>)}</div> : <Empty icon={KeyRound} title="No API keys" copy="Create a scoped key for a trusted server integration." />}</section>
    <section className="band"><div className="section-title"><div><h2>Core endpoints</h2><p>Send the key as <code>Authorization: Bearer vcp_live_...</code>. Responses are JSON.</p></div></div><div className="detail-grid"><div><span>Service health</span><code>GET /api/platform/health</code></div><div><span>Organization extensions</span><code>GET /api/platform/extensions</code></div><div><span>Active calls / dial</span><code>GET · POST /api/platform/calls</code></div><div><span>Call action</span><code>PATCH /api/platform/calls</code></div><div><span>Inventory / purchase</span><code>GET · POST /api/platform/numbers</code></div><div><span>Call events</span><code>GET /api/platform/events</code></div></div><div className="info-strip"><ShieldCheck /><span>Public phone-number purchases require <code>confirmPurchase: true</code>. PSTN transport and regulated numbering remain on Telnyx while Vocivo owns authentication, tenancy, routing policy and the API surface.</span></div></section>
  </div>;
}

function NumbersPage({ data, onRefresh }) {
  const [form, setForm] = useState({ country: 'US', areaCode: '', locality: '', type: 'local', features: 'voice' });
  const [results, setResults] = useState([]), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const search = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const query = new URLSearchParams(form); const response = await api(`/api/admin/numbers?mode=search&${query}`); setResults(response.numbers || []); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const buy = async (item) => {
    const price = `${item.currency} ${item.upfrontCost} now and ${item.monthlyCost}/month`;
    if (!confirm(`Purchase ${item.phoneNumber} for ${price}? This will charge the connected Telnyx account.`)) return;
    setBusy(true); setError('');
    try { await api('/api/admin/numbers', { method: 'POST', body: { phoneNumbers: [item.phoneNumber], confirmPurchase: true, customerReference: 'Vocivo admin purchase' } }); setResults((current) => current.filter((number) => number.phoneNumber !== item.phoneNumber)); await onRefresh(); }
    catch (err) { setError(err.message); } finally { setBusy(false); }
  };
  const assign = async (item) => { if (!confirm(`Route incoming calls for ${item.phoneNumber} through the Vocivo business voice application?`)) return; setBusy(true); setError(''); try { await api('/api/admin/numbers', { method: 'PATCH', body: { id: item.id, assignToVocivo: true } }); await onRefresh(); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  return <div className="page"><PageHeader eyebrow="NUMBER MANAGEMENT" title="Phone numbers" subtitle="Search global inventory, review pricing, purchase and monitor provisioning."><button className="secondary" onClick={onRefresh}><RefreshCw /> Refresh</button></PageHeader>
    <section className="band"><div className="section-title"><div><h2>Buy a number</h2><p>Availability, capabilities and pricing come directly from the carrier inventory.</p></div></div><form className="form-grid" onSubmit={search}><Field label="Country"><select value={form.country} onChange={(e) => setForm({ ...form, country: e.target.value })}>{countryOptions.map((country) => <option key={country.country_code} value={country.country_code}>{country.country_name} ({country.country_code})</option>)}</select></Field><Field label="Number type"><select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}><option value="local">Local</option><option value="toll-free">Toll-free</option><option value="mobile">Mobile</option><option value="national">National</option><option value="shared-cost">Shared cost</option></select></Field><Field label="Area code"><input value={form.areaCode} onChange={(e) => setForm({ ...form, areaCode: e.target.value.replace(/\D/g, '') })} placeholder="Optional" /></Field><Field label="City or locality"><input value={form.locality} onChange={(e) => setForm({ ...form, locality: e.target.value })} placeholder="Optional" /></Field><Field label="Required feature"><select value={form.features} onChange={(e) => setForm({ ...form, features: e.target.value })}><option value="voice">Voice</option><option value="sms">SMS</option><option value="fax">Fax</option><option value="emergency">Emergency capable</option></select></Field><div className="field"><span>&nbsp;</span><button className="primary" disabled={busy}><Search /> Search inventory</button></div></form>{error && <div className="info-strip"><ShieldCheck /><span>{error}</span></div>}
      {results.length > 0 && <div className="table-shell number-results"><table><thead><tr><th>Number</th><th>Type / locality</th><th>Features</th><th>Upfront</th><th>Monthly</th><th /></tr></thead><tbody>{results.map((item) => <tr key={item.phoneNumber}><td><strong>{item.phoneNumber}</strong></td><td>{item.type}<small>{item.locality || 'Global inventory'}</small></td><td>{item.features.join(', ') || 'Voice'}</td><td>{item.currency} {item.upfrontCost}</td><td>{item.currency} {item.monthlyCost}</td><td><button className="primary" onClick={() => buy(item)} disabled={busy}>Purchase</button></td></tr>)}</tbody></table></div>}
    </section>
    <section className="band"><div className="section-title"><div><h2>Owned numbers</h2><p>Active numbers and their current voice connection.</p></div><Status good>{data?.numbers?.length || 0} active</Status></div>{data?.numbers?.length ? <div className="table-shell"><table><thead><tr><th>Number</th><th>Country</th><th>Connection</th><th>Messaging</th><th>Status</th><th /></tr></thead><tbody>{data.numbers.map((item) => <tr key={item.id}><td><strong>{item.phoneNumber}</strong><small>{item.tags?.join(', ') || 'No label'}</small></td><td>{item.country || '-'}</td><td>{item.connectionName || item.connectionId || 'Unassigned'}</td><td>{item.messagingProfileId ? 'Configured' : 'Not configured'}</td><td><Status good={item.status === 'active'}>{item.status || 'unknown'}</Status></td><td><button className="secondary" onClick={() => assign(item)} disabled={busy}>Use for inbound</button></td></tr>)}</tbody></table></div> : <Empty icon={PhoneIncoming} title="No active phone numbers" copy="Search carrier inventory to add the first number." />}</section>
    <section className="band"><div className="section-title"><div><h2>Recent orders</h2><p>Orders that need documents remain pending until regulatory review is complete.</p></div></div>{data?.orders?.length ? <div className="event-list">{data.orders.slice(0, 10).map((item) => <div key={item.id}><CircleDot /><strong>{item.count || 0} number order</strong><span>{item.status}{item.requirementsMet === false ? ' · requirements pending' : ''}</span><time>{item.createdAt ? new Date(item.createdAt).toLocaleString() : ''}</time></div>)}</div> : <Empty icon={FileClock} title="No recent number orders" copy="Completed purchases will appear here." />}</section>
  </div>;
}

function TrunksPage({ data, onAdd, onEdit, onDelete }) { const p = data?.vocivoTrunk; return <div className="page"><PageHeader eyebrow="VOICE INFRASTRUCTURE" title="SIP trunks" subtitle="Inbound and outbound carrier routes, registration, security and failover."><button className="primary" onClick={onAdd}><Plus /> Add SIP trunk</button></PageHeader><section className="band"><div className="section-title"><div><h2>Vocivo managed connection</h2><p>Credential-based registration used by mobile and web clients.</p></div><Status good={p?.active}>{p?.active ? 'Active' : 'Inactive'}</Status></div><div className="detail-grid"><div><span>SIP host</span><strong>{p?.host || 'sip.telnyx.com'}</strong></div><div><span>Registration</span><strong>{p?.registrationStatus || 'Unknown'}</strong></div><div><span>Transport</span><strong>{p?.transport || 'WSS / TLS'}</strong></div><div><span>Codecs</span><strong>{p?.codecs?.join(', ') || 'G.711, G.722'}</strong></div><div><span>SIP URI calling</span><strong>{p?.sipUriCalling || 'Internal'}</strong></div><div><span>Authentication user</span><code>{p?.username || 'Unavailable'}</code></div></div></section><section className="band"><div className="section-title"><div><h2>External PBX registrations</h2><p>Connect 3CX, Cisco, Asterisk or an SBC with controlled call directions.</p></div></div>{data?.externalTrunks?.length ? <div className="object-list">{data.externalTrunks.map((x) => <div key={x.id}><span className="object-icon"><Server /></span><div><strong>{x.name}</strong><small>{x.proxy} · {x.transport} · {x.policy?.inboundEnabled ? 'Inbound' : ''}{x.policy?.inboundEnabled && x.policy?.outboundEnabled ? ' + ' : ''}{x.policy?.outboundEnabled ? 'Outbound' : ''} · {x.policy?.channelLimit || 10} channels</small></div><Status good={x.active && x.registrationStatus?.toLowerCase() === 'registered'} warn={x.active}>{x.registrationStatus || (x.active ? 'Active' : 'Inactive')}</Status><div className="row-actions"><button onClick={() => onEdit(x)}>Edit</button><button className="danger icon-button" onClick={() => onDelete(x)}><Trash2 /></button></div></div>)}</div> : <Empty icon={Network} title="No external trunks" copy="The managed Telnyx connection remains active." />}</section></div>; }
function SystemPage({ config, setConfig, overview, onSave }) {
  const organizationIndex = Math.max(0, config.organizations.findIndex((item) => item.id === config.activeOrganizationId));
  const organization = config.organizations[organizationIndex];
  const updateOrganization = (change) => setConfig({ ...config, organizations: config.organizations.map((item, index) => index === organizationIndex ? { ...item, ...change } : item) });
  return <div className="page"><PageHeader eyebrow="PLATFORM SETTINGS" title="System" subtitle="Company identity, extension allocation, security and platform status."><button className="primary" onClick={onSave}><Save /> Save settings</button></PageHeader>
    <section className="band"><div className="section-title"><div><h2>Organization</h2><p>Defaults inherited by users and call routes.</p></div></div><div className="form-grid"><Field label="Company name"><input value={config.company.name} onChange={(e) => setConfig({ ...config, company: { ...config.company, name: e.target.value }, organizations: config.organizations.map((item, index) => index === organizationIndex ? { ...item, name: e.target.value } : item) })} /></Field><Field label="Timezone"><input value={config.company.timezone} onChange={(e) => setConfig({ ...config, company: { ...config.company, timezone: e.target.value } })} /></Field><Field label="Default outbound caller ID"><input value={config.company.defaultCallerId} onChange={(e) => setConfig({ ...config, company: { ...config.company, defaultCallerId: e.target.value } })} /></Field><Field label="Emergency service address"><input value={config.company.emergencyAddress} onChange={(e) => setConfig({ ...config, company: { ...config.company, emergencyAddress: e.target.value } })} /></Field></div></section>
    <section className="band"><div className="section-title"><div><h2>Internal extension allocation</h2><p>Reserve a private numberless calling range for this organization.</p></div><Status good={organization?.internalCallingEnabled}>{organization?.internalCallingEnabled ? 'Enabled' : 'Disabled'}</Status></div><div className="form-grid"><Field label="First extension" help="Two to five digits."><input type="number" min="10" max="99999" value={organization?.extensionStart ?? 2000} onChange={(e) => updateOrganization({ extensionStart: Number(e.target.value) })} /></Field><Field label="Last extension" help="The inclusive end of this company's allocation."><input type="number" min="10" max="99999" value={organization?.extensionEnd ?? 2019} onChange={(e) => updateOrganization({ extensionEnd: Number(e.target.value) })} /></Field></div><div className="setting-line"><div><strong>Free internal calling</strong><span>Users in this organization can dial extensions without a public phone number or PSTN charge.</span></div><Toggle value={organization?.internalCallingEnabled !== false} onChange={(internalCallingEnabled) => updateOrganization({ internalCallingEnabled })} /></div><div className="info-strip"><PhoneCall /><span>{organization ? `${organization.extensionEnd - organization.extensionStart + 1} private extension slots allocated from ${organization.extensionStart} to ${organization.extensionEnd}.` : 'Configure an organization range.'}</span></div></section>
    <section className="band"><div className="section-title"><div><h2>Compliance and retention</h2><p>Enable only after legal and operational review.</p></div></div><div className="setting-line"><div><strong>Call recording</strong><span>Allow recording controls for permitted users.</span></div><Toggle value={config.system.recordingEnabled} onChange={(recordingEnabled) => setConfig({ ...config, system: { ...config.system, recordingEnabled } })} /></div><div className="setting-line"><div><strong>Emergency calling</strong><span>Requires a verified service address and route.</span></div><Toggle value={config.system.emergencyCallingEnabled} onChange={(emergencyCallingEnabled) => setConfig({ ...config, system: { ...config.system, emergencyCallingEnabled } })} /></div><div className="form-grid"><Field label="Recording retention"><div className="suffix-input"><input type="number" min="1" max="3650" value={config.system.retentionDays} onChange={(e) => setConfig({ ...config, system: { ...config.system, retentionDays: Number(e.target.value) } })} /><span>days</span></div></Field></div></section>
    <section className="band"><div className="section-title"><div><h2>Platform information</h2><p>Current production connection information.</p></div></div><div className="detail-grid"><div><span>Voice connection</span><strong>{overview?.connection?.name || 'Vocivo Mobile'}</strong></div><div><span>Connection status</span><strong>{overview?.connection?.active ? 'Active' : 'Inactive'}</strong></div><div><span>Incoming iOS push</span><strong>{overview?.connection?.pushConfigured ? 'Configured' : 'Not configured'}</strong></div><div><span>Control / media plane</span><strong>{config.platform.controlPlane} / {config.platform.mediaPlane}</strong></div><div><span>Configuration updated</span><strong>{new Date(config.updatedAt).toLocaleString()}</strong></div></div></section>
  </div>;
}

export default function AdminConsole() {
  const [section, setSection] = useState('dashboard'), [overview, setOverview] = useState(null), [extensions, setExtensions] = useState([]), [trunks, setTrunks] = useState(null), [numberData, setNumberData] = useState({ numbers: [], orders: [] }), [voiceData, setVoiceData] = useState(null), [platformKeys, setPlatformKeys] = useState([]), [revealedToken, setRevealedToken] = useState(''), [events, setEvents] = useState([]);
  const [business, setBusiness] = useState({ enabled: false, companyName: 'Global Heritage', greeting: '', waitingMessage: '', departments: ['Sales', 'Operations'], voice: 'AWS.Polly.Joanna-Neural', backgroundImageUrl: '' });
  const [config, setConfig] = useState(null), [userDraft, setUserDraft] = useState(null), [userProfile, setUserProfile] = useState(defaultProfile), [trunkDraft, setTrunkDraft] = useState(null), [enrollment, setEnrollment] = useState(null), [busy, setBusy] = useState(false), [error, setError] = useState('');
  async function load() { setBusy(true); setError(''); try { const [o, u, t, n, v, k, b, p] = await Promise.all([api('/api/admin/overview'), api('/api/admin/extensions'), api('/api/admin/trunks'), api('/api/admin/numbers'), api('/api/admin/voices'), api('/api/admin/api-keys'), api('/api/voice/settings'), api('/api/admin/pbx')]); setOverview(o); setExtensions(u.extensions || []); setTrunks(t); setNumberData(n); setVoiceData(v); setPlatformKeys(k.keys || []); setBusiness(b.config || business); setConfig(p.config); api('/api/admin/events').then((e) => setEvents(e.events || [])).catch(() => setEvents([])); } catch (err) { setError(err.message); } finally { setBusy(false); } }
  useEffect(() => { load(); }, []);
  if (!config) return <div className="admin-loading"><RefreshCw /><strong>Loading business phone system</strong>{error && <span>{error}</span>}</div>;
  const saveConfig = async (next = config) => { setBusy(true); setError(''); try { const result = await api('/api/admin/pbx', { method: 'PUT', body: next }); setConfig(result.config); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const openUser = (item = emptyUser) => { setUserDraft({ ...item }); const stored = item.id ? config.userProfiles[item.id] || {} : {}; setUserProfile({ ...defaultProfile, ...stored, permissions: { ...defaultProfile.permissions, ...(stored.permissions || {}) } }); };
  const saveUser = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const editing = Boolean(userDraft.id); const result = await api('/api/admin/extensions', { method: editing ? 'PATCH' : 'POST', body: userDraft }); const saved = result.extension; const p = await api('/api/admin/pbx', { method: 'PUT', body: { ...config, userProfiles: { ...config.userProfiles, [saved.id]: userProfile } } }); setConfig(p.config); setUserDraft(null); await load(); if (!editing) await provisionUser(saved); } catch (err) { setError(err.message); setBusy(false); } };
  const deleteUser = async (item) => { if (!confirm(`Remove ${item.name} and revoke extension ${item.extension}?`)) return; try { await api(`/api/admin/extensions?id=${encodeURIComponent(item.id)}`, { method: 'DELETE' }); const profiles = { ...config.userProfiles }; delete profiles[item.id]; await saveConfig({ ...config, userProfiles: profiles }); await load(); } catch (err) { setError(err.message); } };
  const provisionUser = async (item) => { setBusy(true); try { const result = await api('/api/admin/enrollments', { method: 'POST', body: { extensionId: item.id } }); const qrDataUrl = await QRCode.toDataURL(result.provisioningUri, { width: 440, margin: 2, errorCorrectionLevel: 'M', color: { dark: '#0b315b', light: '#ffffff' } }); setEnrollment({ ...result, qrDataUrl }); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const saveBusiness = async () => { setBusy(true); try { const result = await api('/api/voice/settings', { method: 'PUT', body: business }); setBusiness(result.config); await saveConfig(config); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const saveAI = async () => { setBusy(true); try { const result = await api('/api/admin/ai', { method: 'PUT', body: config.ai }); const next = { ...config, ai: result.ai }; setConfig(next); await saveConfig(next); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const uploadBackground = async (file) => { if (!file) return; setBusy(true); try { const base64 = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(file); }); const result = await api('/api/admin/background', { method: 'POST', body: { contentType: file.type, base64 } }); setBusiness({ ...business, backgroundImageUrl: result.url }); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const exportUsers = () => { const csv = ['Extension,Name,Email,Mobile,Department,Role', ...extensions.map((x) => [x.extension, x.name, x.email, x.mobile, x.department, x.role].map((v) => `"${String(v || '').replaceAll('"', '""')}"`).join(','))].join('\n'); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' })); const a = document.createElement('a'); a.href = url; a.download = 'vocivo-users.csv'; a.click(); URL.revokeObjectURL(url); };
  const saveTrunk = async (event) => { event.preventDefault(); setBusy(true); try { await api('/api/admin/trunks', { method: trunkDraft.id ? 'PATCH' : 'POST', body: trunkDraft }); setTrunkDraft(null); await load(); } catch (err) { setError(err.message); setBusy(false); } };
  const deleteTrunk = async (item) => { if (!confirm(`Delete SIP trunk ${item.name}?`)) return; try { await api(`/api/admin/trunks?id=${encodeURIComponent(item.id)}`, { method: 'DELETE' }); await load(); } catch (err) { setError(err.message); } };
  const refreshNumbers = async () => { const result = await api('/api/admin/numbers'); setNumberData(result); };
  const createApiKey = async () => { const name = prompt('Name this server API key'); if (!name?.trim()) return; try { const result = await api('/api/admin/api-keys', { method: 'POST', body: { name: name.trim() } }); setPlatformKeys((current) => [...current, result.key]); setRevealedToken(result.token); } catch (err) { setError(err.message); } };
  const revokeApiKey = async (item) => { if (!confirm(`Revoke ${item.name}? Existing integrations using it will stop immediately.`)) return; try { const result = await api(`/api/admin/api-keys?id=${encodeURIComponent(item.id)}`, { method: 'DELETE' }); setPlatformKeys((current) => current.map((key) => key.id === item.id ? result.key : key)); } catch (err) { setError(err.message); } };
  const pages = {
    dashboard: <Dashboard overview={overview} extensions={extensions} config={config} events={events} setSection={setSection} />, users: <UsersPage items={extensions} onAdd={() => openUser()} onEdit={openUser} onDelete={deleteUser} onProvision={provisionUser} onExport={exportUsers} />, numbers: <NumbersPage data={numberData} onRefresh={refreshNumbers} />,
    voice: <VoicePage business={business} setBusiness={setBusiness} config={config} setConfig={setConfig} voices={voiceData} onSaveBusiness={saveBusiness} onSaveAI={saveAI} onUpload={uploadBackground} busy={busy} />, outbound: <OutboundPage config={config} setConfig={setConfig} onSave={() => saveConfig()} />,
    hours: <HoursPage config={config} setConfig={setConfig} onSave={() => saveConfig()} />, handling: <HandlingPage config={config} setConfig={setConfig} onSave={() => saveConfig()} />, reports: <ReportsPage events={events} />, events: <EventsPage events={events} />,
    trunks: <TrunksPage data={trunks} onAdd={() => setTrunkDraft(emptyTrunk)} onEdit={(item) => setTrunkDraft({ ...emptyTrunk, ...item, password: '', policy: { ...emptyTrunk.policy, ...(item.policy || {}) } })} onDelete={deleteTrunk} />, developer: <DeveloperPage data={platformKeys} revealedToken={revealedToken} onCreate={createApiKey} onRevoke={revokeApiKey} onClearToken={() => setRevealedToken('')} />, system: <SystemPage config={config} setConfig={setConfig} overview={overview} onSave={() => saveConfig()} />,
  };
  return <section className="admin-console"><aside><div className="admin-brand"><span><PhoneCall /></span><div><strong>Vocivo</strong><small>Admin Console</small></div></div><div className="tenant"><Building2 /><div><strong>{config.company.name}</strong><small>Production organization</small></div><ChevronDown /></div>{nav.map((group) => <div className="nav-group" key={group.group}><p>{group.group}</p>{group.items.map(([id, Icon, label]) => <button key={id} className={section === id ? 'active' : ''} onClick={() => setSection(id)}><Icon />{label}</button>)}</div>)}<div className="nav-health"><i /><div><strong>Voice system online</strong><small>Telnyx production</small></div></div></aside><main>{error && <div className="error-banner"><span>{error}</span><button onClick={() => setError('')}><X /></button></div>}<div className="topbar"><div><span className="top-status"><i /> Production</span><span>{extensions.length} users</span></div><button className="icon-button" title="Refresh system" onClick={load} disabled={busy}><RefreshCw className={busy ? 'spin' : ''} /></button></div>{pages[section]}</main>
    {userDraft && <UserEditor draft={userDraft} profile={userProfile} organization={config.organizations.find((item) => item.id === config.activeOrganizationId)} onDraft={setUserDraft} onProfile={setUserProfile} onClose={() => setUserDraft(null)} onSave={saveUser} onProvision={provisionUser} busy={busy} />}
    {enrollment && <Modal title={`Set up ${enrollment.extension.name}`} subtitle={`Extension ${enrollment.extension.extension} · expires in 10 minutes`} onClose={() => setEnrollment(null)}><div className="enrollment"><img src={enrollment.qrDataUrl} alt={`Setup QR for extension ${enrollment.extension.extension}`} /><div><h3>Scan with iPhone Camera</h3><ol><li>Open Camera and scan this QR.</li><li>Tap the Vocivo setup page.</li><li>Tap Open Vocivo to finish.</li></ol><div className="info-strip"><ShieldCheck /><span>The code is single-purpose and never shows the SIP password.</span></div><button className="secondary" onClick={() => navigator.clipboard.writeText(enrollment.provisioningUri)}>Copy setup link</button></div></div></Modal>}
    {trunkDraft && <Modal wide title={trunkDraft.id ? `Edit ${trunkDraft.name}` : 'Add SIP trunk'} subtitle="Register an external PBX and define its inbound and outbound policy" onClose={() => setTrunkDraft(null)}><form className="modal-form form-grid" onSubmit={saveTrunk}><Field label="Trunk name"><input value={trunkDraft.name} onChange={(e) => setTrunkDraft({ ...trunkDraft, name: e.target.value })} required /></Field><Field label="Registrar / proxy"><input value={trunkDraft.proxy} onChange={(e) => setTrunkDraft({ ...trunkDraft, proxy: e.target.value })} placeholder="sip:pbx.example.com:5061" required /></Field><Field label="Username"><input value={trunkDraft.username} onChange={(e) => setTrunkDraft({ ...trunkDraft, username: e.target.value })} required /></Field><Field label="Password" help={trunkDraft.id ? 'Leave blank to keep the existing secret.' : 'Stored only by the carrier; never returned to the browser.'}><input type="password" value={trunkDraft.password} onChange={(e) => setTrunkDraft({ ...trunkDraft, password: e.target.value })} required={!trunkDraft.id} /></Field><Field label="Transport"><select value={trunkDraft.transport} onChange={(e) => setTrunkDraft({ ...trunkDraft, transport: e.target.value })}><option>TLS</option><option>TCP</option><option>UDP</option></select></Field><Field label="Telnyx application destination" help="Routes calls received from the PBX into a Telnyx application."><input value={trunkDraft.destinationUri} onChange={(e) => setTrunkDraft({ ...trunkDraft, destinationUri: e.target.value })} placeholder="2000@cc-app-id.sip.telnyx.com" /></Field><Field label="Inbound DIDs" help="Comma-separated public numbers assigned to this route."><input value={(trunkDraft.policy.inboundDids || []).join(', ')} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, inboundDids: e.target.value.split(',').map((x) => x.trim()).filter(Boolean) } })} placeholder="+18447161777" /></Field><Field label="Default inbound destination"><input value={trunkDraft.policy.defaultDestination} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, defaultDestination: e.target.value } })} placeholder="Extension, ring group or SIP URI" /></Field><Field label="Outbound prefix"><input value={trunkDraft.policy.outboundPrefix} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, outboundPrefix: e.target.value } })} placeholder="Optional access code" /></Field><Field label="Route priority"><input type="number" min="1" max="100" value={trunkDraft.policy.priority} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, priority: Number(e.target.value) } })} /></Field><Field label="Channel limit"><input type="number" min="1" max="10000" value={trunkDraft.policy.channelLimit} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, channelLimit: Number(e.target.value) } })} /></Field><Field label="Failover trunk"><select value={trunkDraft.policy.failoverTrunkId} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, failoverTrunkId: e.target.value } })}><option value="">No failover</option>{(trunks?.externalTrunks || []).filter((x) => x.id !== trunkDraft.id).map((x) => <option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Codecs"><input value={(trunkDraft.policy.codecs || []).join(', ')} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, codecs: e.target.value.toUpperCase().split(',').map((x) => x.trim()).filter(Boolean) } })} placeholder="PCMU, PCMA, G722, OPUS" /></Field><Field label="Notes"><input value={trunkDraft.policy.notes} onChange={(e) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, notes: e.target.value } })} /></Field><div className="setting-line wide"><div><strong>Inbound calling</strong><span>Accept calls from this PBX and apply inbound routes.</span></div><Toggle value={trunkDraft.policy.inboundEnabled} onChange={(inboundEnabled) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, inboundEnabled } })} /></div><div className="setting-line wide"><div><strong>Outbound calling</strong><span>Allow this organization to select the trunk in outbound rules.</span></div><Toggle value={trunkDraft.policy.outboundEnabled} onChange={(outboundEnabled) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, outboundEnabled } })} /></div><div className="setting-line wide"><div><strong>Encrypted media</strong><span>Require secure media where supported by both peers.</span></div><Toggle value={trunkDraft.policy.mediaEncryption} onChange={(mediaEncryption) => setTrunkDraft({ ...trunkDraft, policy: { ...trunkDraft.policy, mediaEncryption } })} /></div><footer className="wide"><button type="button" className="secondary" onClick={() => setTrunkDraft(null)}>Cancel</button><button className="primary"><Save /> Save trunk</button></footer></form></Modal>}
  </section>;
}
